use std::{fs,path::Path};
use serde_json::{json,Value};
use open_pipe_stress_headless_runner::{RunnerRequest,run_preview_model_value,run_preview_model_value_with_mode,result_envelope_binding::{build_result_export_document_with_evidence,build_result_export_document}};
use open_pipe_stress_product_physics::PreviewSolverMode;
fn read(p:&Path)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn write(p:&Path,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap();}
fn main(){let args:Vec<String>=std::env::args().collect();if args[1]=="--serializer-compare"{compare(Path::new(&args[2]),Path::new(&args[3]),Path::new(&args[4]));return;}let root=Path::new(&args[1]);let out=Path::new(&args[2]);fs::create_dir_all(out).unwrap();let baseline=root.join("TASK_WRITER/baseline_outputs_v1");let gap=root.join("NONCONVERGENCE_DIAGNOSIS_V1/inputs_attempt_02");let mut records=vec![];
for (dir,cases) in [(&baseline,vec!["straight-full","curved-tip-weight-full","curved-pressure-full","straight-sparse-full","straight-dense-full","blocked","nonconverged-candidate-0","nonconverged-candidate-1","nonconverged-candidate-2","nonconverged-candidate-3","nonconverged-candidate-4","nonconverged-candidate-5"]),(&gap,vec!["gap-chain-five-active","gap-chain-two-active-control","gap-chain-five-inactive-control"])] {
for case in cases {let modelpath=dir.join(format!("{case}.model.json"));let requestpath=dir.join(format!("{case}.request.json"));if !modelpath.exists(){panic!("missing actual original input {}",modelpath.display());}let model=read(&modelpath);let request_value=read(&requestpath);let request:RunnerRequest=serde_json::from_value(request_value.clone()).unwrap();let payload=json!({"model":model,"materials":[]});let (output,route)=match case {"straight-dense-full"=>(run_preview_model_value_with_mode(request.clone(),payload,PreviewSolverMode::DenseScrutiny).unwrap(),"lower_level_explicit_dense_scrutiny"),"straight-sparse-full"=>(run_preview_model_value_with_mode(request.clone(),payload,PreviewSolverMode::SparseInteractive).unwrap(),"lower_level_explicit_sparse_interactive"),_=>(run_preview_model_value(request.clone(),payload).unwrap(),"default_attached_sparse_model_aware")};
write(&out.join(format!("{case}.model.json")),&model);write(&out.join(format!("{case}.request.json")),&request_value);write(&out.join(format!("{case}.runner.json")),&serde_json::to_value(&output).unwrap());let mechanics=output.mechanics_envelope.as_ref().unwrap();let source=serde_json::to_value(mechanics).unwrap();write(&out.join(format!("{case}.received.json")),&source);let old=build_result_export_document(&request,&output.runner_result,mechanics);let mut equal=Value::Null;let mut changed_reject=Value::Null;let mut changed_request_reject=Value::Null;
if let Some(doc)=output.result_envelope_document.as_ref(){write(&out.join(format!("{case}.document.json")),doc);let proof=output.qualified_preview_evidence.as_ref().unwrap();let explicit=build_result_export_document_with_evidence(&request,&output.runner_result,mechanics,proof).unwrap();assert_eq!(doc,&explicit);write(&out.join(format!("{case}.explicit.json")),&explicit);equal=json!(true);let mut altered=mechanics.clone();altered.results[0].value+=1.0;changed_reject=json!(build_result_export_document_with_evidence(&request,&output.runner_result,&altered,proof).is_err());let mut altered_request=request.clone();altered_request.model_ref.ref_id.push_str("-changed");changed_request_reject=json!(build_result_export_document_with_evidence(&altered_request,&output.runner_result,mechanics,proof).is_err());assert_eq!(changed_reject,true);assert_eq!(changed_request_reject,true);}
records.push(json!({"case":case,"route":route,"original_model_input":modelpath,"original_request_input":requestpath,"status":mechanics.status.mechanics,"rows":mechanics.results.len(),"attached_present":output.result_envelope_document.is_some(),"attached_equals_private_library":equal,"legacy_builder_rejected":old.is_err(),"changed_source_rejected":changed_reject,"changed_request_rejected":changed_request_reject,"canonical_unavailability":output.canonical_export_unavailability}));println!("{case}: {} rows {}",mechanics.results.len(),mechanics.status.mechanics);
}}write(&out.join("FRESH_ROUTE_RETURN.json"),&json!({"execution_driver":"fresh_implementation_evidence_only_v1","baseline_cases":12,"additional_gap_cases":3,"records":records}));}

fn compare(root:&Path,fresh:&Path,output:&Path){
 let base=root.join("TASK_WRITER/baseline_outputs_v1");let mut records=vec![];
 for entry in fs::read_dir(&base).unwrap(){let entry=entry.unwrap();let name=entry.file_name().to_string_lossy().into_owned();if !name.ends_with(".mechanics.json"){continue;}let case=name.strip_suffix(".mechanics.json").unwrap();let captured=fresh.join(format!("{case}.received.json"));let typed:open_pipe_stress_product_physics::MechanicsEnvelope=restore_typed(&read(&captured));let serialized=serde_json::to_string_pretty(&typed).unwrap()+"\n";assert_eq!(serialized.as_bytes(),fs::read(entry.path()).unwrap(),"{case} mechanics bytes");
 let wrapper=read(&fresh.join(format!("{case}.runner.json")));let keys:Vec<_>=wrapper.as_object().unwrap().keys().collect();assert_eq!(keys,vec!["mechanics_envelope","runner_result"]);for key in ["result_envelope_document","qualified_preview_evidence","canonical_export_unavailability"]{assert!(wrapper.get(key).is_none());}
 let runner:open_pipe_stress_headless_runner::RunnerResult=serde_json::from_value(wrapper["runner_result"].clone()).unwrap();let runner_serialized=serde_json::to_string_pretty(&runner).unwrap()+"\n";let runner_equal=runner_serialized.as_bytes()==fs::read(base.join(format!("{case}.runner.json"))).unwrap();if case!="straight-dense-full"{assert!(runner_equal,"{case} runner bytes");}else{let old_runner=read(&base.join(format!("{case}.runner.json")));let mut actual=wrapper["runner_result"].clone();actual["result_refs"]=old_runner["result_refs"].clone();assert_eq!(actual,old_runner,"dense runner difference must be exact original default sparse result_refs versus actual dense refs");}
 records.push(json!({"case":case,"mechanics_same_typed_pretty_serializer_bytes_equal":true,"runner_result_same_typed_pretty_serializer_bytes_equal":runner_equal,"runner_scope":if case=="straight-dense-full"{"old baseline retained default sparse runner refs786 while mechanics replaced dense788; fresh actual explicit dense route runner refs788"}else{"same original raw typed RunnerResult"},"private_library_fields_absent":true,"captured_mechanics_file_byte_equal":fs::read(&captured).unwrap()==fs::read(entry.path()).unwrap(),"capture_format":"Value pretty/key-sorted/no trailing newline; distinct from baseline typed pretty plus newline"}));}
 assert_eq!(records.len(),12);write(output,&json!({"cases":12,"no_solve_executed":true,"records":records}));println!("PASS12 typed mechanics serializer bytes;11 runner equal,1 explicit dense attribution difference; private fields absent");}

// Evidence-only reconstruction of existing public output structs, not a solve
// or new product transport. MechanicsEnvelope deliberately has no Deserialize.
fn text(v:&Value,k:&str)->String{v[k].as_str().unwrap().into()}
fn strings(v:&Value)->Vec<String>{v.as_array().map(|a|a.iter().map(|x|x.as_str().unwrap().into()).collect()).unwrap_or_default()}
fn located(v:&Value)->Option<open_pipe_stress_product_physics::LocatedQuantity>{use open_pipe_stress_product_physics::LocatedQuantity;if v.is_null(){None}else{Some(LocatedQuantity{value:v["value"].as_f64().unwrap(),unit:text(v,"unit"),location_ref:text(v,"location_ref"),result_ref:text(v,"result_ref")})}}
fn restore_typed(v:&Value)->open_pipe_stress_product_physics::MechanicsEnvelope{use open_pipe_stress_product_physics::{MechanicsEnvelope,Summary,ResultItem,ResultBasisRef,ResultMetadata,Diagnostic,ProfessionalBoundary};let summary=&v["summary"];let boundary=&v["professional_boundary"];
 MechanicsEnvelope{schema_version:text(v,"schema_version"),document_kind:text(v,"document_kind"),run_id:text(v,"run_id"),model_ref:text(v,"model_ref"),status:serde_json::from_value(v["status"].clone()).unwrap(),summary:Summary{
 node_count:summary["node_count"].as_u64().unwrap() as usize,segment_count:summary["segment_count"].as_u64().unwrap() as usize,support_count:summary["support_count"].as_u64().unwrap() as usize,load_case_count:summary["load_case_count"].as_u64().unwrap() as usize,component_stress_modifier_count:summary["component_stress_modifier_count"].as_u64().unwrap() as usize,component_user_stiffness_macro_element_count:summary["component_user_stiffness_macro_element_count"].as_u64().unwrap() as usize,component_pressure_thrust_load_count:summary["component_pressure_thrust_load_count"].as_u64().unwrap() as usize,spring_hanger_user_input_count:summary["spring_hanger_user_input_count"].as_u64().unwrap() as usize,max_displacement:located(&summary["max_displacement"]),max_open_formula_stress:located(&summary["max_open_formula_stress"])},
 results:v["results"].as_array().unwrap().iter().map(|row|ResultItem{id:text(row,"id"),kind:text(row,"kind"),value:row["value"].as_f64().unwrap(),unit:text(row,"unit"),entity_ref:text(row,"entity_ref"),basis_ref:row.get("basis_ref").filter(|b|!b.is_null()).map(|b|ResultBasisRef{ref_type:text(b,"ref_type"),ref_id:text(b,"ref_id")}),source_result_refs:strings(&row["source_result_refs"]),metadata:row.get("metadata").filter(|m|!m.is_null()).map(|m|ResultMetadata{component:text(m,"component"),coordinate_system:text(m,"coordinate_system"),location:text(m,"location"),basis:text(m,"basis"),sign_convention:text(m,"sign_convention")})}).collect(),
 diagnostics:v["diagnostics"].as_array().unwrap().iter().map(|d|Diagnostic{id:text(d,"id"),code:text(d,"code"),severity:text(d,"severity"),message:text(d,"message"),source:d["source"].as_str().map(String::from),affected_refs:strings(&d["affected_refs"])}).collect(),professional_boundary:ProfessionalBoundary{human_review_required:boundary["human_review_required"].as_bool().unwrap(),software_makes_compliance_claim:boundary["software_makes_compliance_claim"].as_bool().unwrap(),software_makes_certification_claim:boundary["software_makes_certification_claim"].as_bool().unwrap(),software_makes_sealing_claim:boundary["software_makes_sealing_claim"].as_bool().unwrap(),software_makes_approval_claim:boundary["software_makes_approval_claim"].as_bool().unwrap()},accepted_model_state_mutated:v["accepted_model_state_mutated"].as_bool().unwrap()}
}
